@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-primary: #0d1117;
  --bg-surface: #161b22;
  --bg-surface-hover: #1c2330;
  --bg-elevated: #21262d;
  --border-default: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent-green: #00e87b;
  --accent-green-dim: rgba(0, 232, 123, 0.15);
  --accent-cyan: #58a6ff;
  --accent-cyan-dim: rgba(88, 166, 255, 0.12);
  --accent-orange: #f0883e;
  --accent-purple: #bc8cff;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
  --shadow-glow-green: 0 0 20px rgba(0,232,123,0.15);
  --shadow-glow-cyan: 0 0 20px rgba(88,166,255,0.15);
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 64px;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}
a:hover { color: var(--accent-green); }
a:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
  border-radius: 2px;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-primary);
}

h1 { font-size: 2.5rem; letter-spacing: -0.02em; }
h2 { font-size: 1.75rem; letter-spacing: -0.01em; }
h3 { font-size: 1.25rem; }
h4 { font-size: 1.1rem; }

p { color: var(--text-secondary); max-width: 68ch; }

code, pre {
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

/* ─── Top Navigation ─── */
.top-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 24px;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.nav-logo svg {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  display: inline-flex;
  align-items: center;
  padding: 8px 14px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.nav-links a:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}

.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: border-color var(--transition-fast);
}
.nav-search:hover { border-color: var(--text-muted); }
.nav-search svg { width: 14px; height: 14px; opacity: 0.6; }
.nav-search kbd {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  padding: 1px 5px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: 4px;
  color: var(--text-muted);
}

.nav-login {
  padding: 6px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  background: transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.nav-login:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}
.mobile-menu-btn svg { width: 24px; height: 24px; }

/* ─── Main Content Area ─── */
main {
  margin-top: var(--nav-height);
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Hero Section ─── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-green) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero .subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover {
  background: #00ff88;
  color: #0d1117;
  box-shadow: var(--shadow-glow-green);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-default);
}
.btn-secondary:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 8px 12px;
}
.btn-ghost:hover {
  background: var(--accent-cyan-dim);
  color: var(--accent-cyan);
}

/* ─── Product Cards ─── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  padding-bottom: 80px;
}

.product-card {
  position: relative;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  transition: opacity var(--transition-base);
  opacity: 0.7;
}
.product-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-card:hover::before { opacity: 1; }

.product-card.card-apps::before { background: var(--accent-green); }
.product-card.card-storefronts::before { background: var(--accent-cyan); }
.product-card.card-agents::before { background: var(--accent-purple); }

.product-card .card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.card-apps .card-icon { background: var(--accent-green-dim); color: var(--accent-green); }
.card-storefronts .card-icon { background: var(--accent-cyan-dim); color: var(--accent-cyan); }
.card-agents .card-icon { background: rgba(188,140,255,0.12); color: var(--accent-purple); }

.product-card .card-icon svg { width: 24px; height: 24px; }

.product-card h3 { margin-bottom: 12px; }

.product-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  flex: 1;
}

.product-card .btn { align-self: flex-start; }

/* ─── CLI Setup Section ─── */
.cli-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.cli-section .section-header {
  margin-bottom: 48px;
}

.cli-section .section-header h2 { margin-bottom: 12px; }
.cli-section .section-header p { font-size: 1rem; }

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

.accordion-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-trigger {
  width: 100%;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background var(--transition-fast);
}
.accordion-trigger:hover { background: var(--bg-surface-hover); }

.accordion-trigger svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.accordion-item.active .accordion-trigger svg {
  transform: rotate(180deg);
}
.accordion-item.active .accordion-trigger {
  color: var(--accent-green);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow) ease;
}

.accordion-item.active .accordion-body {
  max-height: 500px;
}

.accordion-body-inner {
  padding: 0 20px 20px;
}

.accordion-body-inner ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-body-inner ol li {
  counter-increment: steps;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-body-inner ol li::before {
  content: counter(steps);
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-green-dim);
  color: var(--accent-green);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  margin-top: 1px;
}

.cli-code-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.pkg-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-default);
}

.pkg-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.pkg-tab:hover { color: var(--text-secondary); }
.pkg-tab.active {
  color: var(--accent-green);
  border-bottom-color: var(--accent-green);
}

.code-blocks { padding: 20px; }

.code-block {
  display: none;
}
.code-block.active { display: block; }

.code-block-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 8px;
}

.code-block pre {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  overflow-x: auto;
  margin-bottom: 16px;
}

.code-block pre code {
  color: var(--text-primary);
  font-size: 0.8rem;
  line-height: 1.6;
}

.code-block pre code .cmd { color: var(--accent-cyan); }
.code-block pre code .flag { color: var(--accent-orange); }
.code-block pre code .str { color: var(--accent-green); }
.code-block pre code .comment { color: var(--text-muted); }

/* ─── Launch CTA Section ─── */
.launch-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.launch-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}
.launch-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.launch-card h3 { margin-bottom: 12px; }
.launch-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ─── Community Section ─── */
.community-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.community-section h2 { margin-bottom: 32px; }

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition-base);
  text-decoration: none;
  cursor: pointer;
}
.community-card:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface-hover);
  transform: translateY(-2px);
  color: var(--text-primary);
}
.community-card svg {
  width: 20px;
  height: 20px;
  color: var(--accent-cyan);
  flex-shrink: 0;
}
.community-card span { color: var(--text-secondary); font-weight: 400; font-size: 0.82rem; }

/* ─── Footer ─── */
.site-footer {
  border-top: 1px solid var(--border-default);
  padding: 60px 0 40px;
  margin-top: 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  font-size: 0.85rem;
  color: var(--text-secondary);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* ─── Docs Layout (Sidebar + Content) ─── */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  border-right: 1px solid var(--border-default);
  padding: 24px 0;
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  flex-shrink: 0;
  transition: width var(--transition-slow), padding var(--transition-slow), opacity var(--transition-base);
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: fixed;
  top: calc(var(--nav-height) + 16px);
  left: var(--sidebar-width);
  z-index: 50;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  padding: 6px;
  cursor: pointer;
  transition: all var(--transition-slow);
  display: flex;
  align-items: center;
  justify-content: center;
}
.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}
.sidebar-toggle svg { width: 16px; height: 16px; }

.sidebar.collapsed ~ .sidebar-toggle,
.sidebar-toggle.collapsed-pos {
  left: 8px;
}

.sidebar-nav {
  padding: 0 16px;
}

.sidebar-group { margin-bottom: 24px; }

.sidebar-group-title {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 0 12px;
  margin-bottom: 8px;
}

.sidebar-link {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.sidebar-link:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}
.sidebar-link.active {
  color: var(--accent-green);
  background: var(--accent-green-dim);
}

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px 80px;
  max-width: 900px;
}

.docs-content section {
  margin-bottom: 64px;
}

.docs-content section h2 {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.docs-content section > p {
  margin-bottom: 24px;
}

/* ─── Feature Grid (for surfaces, building blocks, etc.) ─── */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}
.feature-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.feature-card h4 {
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.feature-card h4 svg {
  width: 18px;
  height: 18px;
  color: var(--accent-green);
  flex-shrink: 0;
}

.feature-card p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ─── Best Practices List ─── */
.practices-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 12px;
}

.practice-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}

.practice-item svg {
  width: 18px;
  height: 18px;
  color: var(--accent-green);
  flex-shrink: 0;
  margin-top: 2px;
}

.practice-item strong {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
}

.practice-item span {
  font-size: 0.82rem;
  color: var(--text-secondary);
}

/* ─── Protocol Actors Diagram ─── */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  padding: 32px 0;
}

.actor-card {
  text-align: center;
  padding: 28px 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}
.actor-card:hover {
  border-color: var(--accent-purple);
  box-shadow: 0 0 20px rgba(188,140,255,0.1);
}

.actor-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(188,140,255,0.12);
  color: var(--accent-purple);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
}
.actor-icon svg { width: 24px; height: 24px; }

.actor-card h4 { margin-bottom: 6px; }
.actor-card p { font-size: 0.8rem; color: var(--text-muted); text-align: center; margin: 0 auto; }

/* ─── How-it-works Flow ─── */
.flow-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.flow-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 28px;
  position: relative;
}

.flow-card .flow-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--accent-purple);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}

.flow-card h3 { margin-bottom: 10px; }
.flow-card p { font-size: 0.875rem; color: var(--text-secondary); }

.badge-soon {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--accent-orange);
  background: rgba(240,136,62,0.12);
  padding: 2px 8px;
  border-radius: 999px;
  margin-left: 8px;
  vertical-align: middle;
}

/* ─── Support Categories ─── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.support-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
}
.support-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
}
.support-card h4 { margin-bottom: 10px; }
.support-card ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.support-card li {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

/* ─── Dev Tools Banner ─── */
.dev-tools-banner {
  background: linear-gradient(135deg, var(--bg-surface) 0%, var(--bg-elevated) 100%);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  margin-bottom: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.dev-tools-banner h3 { margin-bottom: 8px; }
.dev-tools-banner p { font-size: 0.9rem; }

/* ─── Section Utilities ─── */
.section-header {
  margin-bottom: 32px;
}
.section-header h2 { margin-bottom: 10px; }
.section-header p { font-size: 1rem; color: var(--text-secondary); }

.section-divider {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 0;
}

/* ─── Tag / Badge ─── */
.tag {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 500;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--accent-green-dim);
  color: var(--accent-green);
}

/* ─── Theming Cards ─── */
.theme-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 32px;
}

.theme-option {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
}
.theme-option:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}
.theme-option h4 { margin-bottom: 8px; }
.theme-option p { font-size: 0.85rem; color: var(--text-secondary); }

.highlights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.highlight-item {
  padding: 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}
.highlight-item h4 { margin-bottom: 6px; font-size: 0.95rem; }
.highlight-item p { font-size: 0.82rem; color: var(--text-secondary); }

/* ─── Inline code ─── */
.inline-code {
  font-family: var(--font-mono);
  font-size: 0.82em;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: 4px;
  padding: 2px 6px;
  color: var(--accent-orange);
}

/* ─── Mobile Responsive ─── */
@media (max-width: 1024px) {
  .product-cards { grid-template-columns: 1fr; }
  .cli-content { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .launch-cards { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .flow-cards { grid-template-columns: 1fr; }
  .theme-options { grid-template-columns: 1fr; }

  .sidebar {
    position: fixed;
    left: 0;
    top: var(--nav-height);
    z-index: 90;
    background: var(--bg-primary);
    width: var(--sidebar-width);
  }
  .sidebar.collapsed { width: 0; }
  .sidebar-toggle {
    position: fixed;
    left: 8px;
  }
  .sidebar:not(.collapsed) ~ .sidebar-toggle { left: calc(var(--sidebar-width) + 4px); }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.35rem; }

  .nav-links, .nav-search { display: none; }
  .mobile-menu-btn { display: flex; }

  .nav-inner { gap: 8px; }

  .hero { padding: 48px 0 32px; }
  .hero .subtitle { font-size: 1rem; }
  .hero-ctas { flex-direction: column; align-items: center; }

  .product-cards { gap: 12px; padding-bottom: 48px; }
  .product-card { padding: 24px 20px; }

  .community-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
  .practices-list { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: 1fr; }

  .docs-content { padding: 24px 20px 48px; }
  .dev-tools-banner { flex-direction: column; text-align: center; }

  .container { padding: 0 16px; }
  .cli-section, .launch-section, .community-section { padding: 48px 0; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
}

/* ─── Mobile Nav Menu ─── */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 99;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--border-default);
}
.mobile-nav.open { display: flex; }

.mobile-nav a {
  display: block;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.mobile-nav a:hover, .mobile-nav a.active {
  color: var(--text-primary);
  background: var(--bg-surface);
}

/* ─── Reduced Motion ─── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ─── Scrollbar ─── */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-primary: #0d1117;
  --bg-surface: #161b22;
  --bg-surface-hover: #1c2330;
  --bg-elevated: #21262d;
  --border-default: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent-green: #00e87b;
  --accent-green-dim: rgba(0, 232, 123, 0.15);
  --accent-cyan: #58a6ff;
  --accent-cyan-dim: rgba(88, 166, 255, 0.12);
  --accent-orange: #f0883e;
  --accent-purple: #bc8cff;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
  --shadow-glow-green: 0 0 20px rgba(0,232,123,0.15);
  --shadow-glow-cyan: 0 0 20px rgba(88,166,255,0.15);
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 64px;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}
a:hover { color: var(--accent-green); }
a:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
  border-radius: 2px;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-primary);
}

h1 { font-size: 2.5rem; letter-spacing: -0.02em; }
h2 { font-size: 1.75rem; letter-spacing: -0.01em; }
h3 { font-size: 1.25rem; }
h4 { font-size: 1.1rem; }

p { color: var(--text-secondary); max-width: 68ch; }

code, pre {
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

/* ─── Top Navigation ─── */
.top-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 24px;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.nav-logo svg {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  display: inline-flex;
  align-items: center;
  padding: 8px 14px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.nav-links a:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}

.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: border-color var(--transition-fast);
}
.nav-search:hover { border-color: var(--text-muted); }
.nav-search svg { width: 14px; height: 14px; opacity: 0.6; }
.nav-search kbd {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  padding: 1px 5px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: 4px;
  color: var(--text-muted);
}

.nav-login {
  padding: 6px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  background: transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.nav-login:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}
.mobile-menu-btn svg { width: 24px; height: 24px; }

/* ─── Main Content Area ─── */
main {
  margin-top: var(--nav-height);
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Hero Section ─── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-green) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero .subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover {
  background: #00ff88;
  color: #0d1117;
  box-shadow: var(--shadow-glow-green);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-default);
}
.btn-secondary:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 8px 12px;
}
.btn-ghost:hover {
  background: var(--accent-cyan-dim);
  color: var(--accent-cyan);
}

/* ─── Product Cards ─── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  padding-bottom: 80px;
}

.product-card {
  position: relative;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  transition: opacity var(--transition-base);
  opacity: 0.7;
}
.product-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-card:hover::before { opacity: 1; }

.product-card.card-apps::before { background: var(--accent-green); }
.product-card.card-storefronts::before { background: var(--accent-cyan); }
.product-card.card-agents::before { background: var(--accent-purple); }

.product-card .card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.card-apps .card-icon { background: var(--accent-green-dim); color: var(--accent-green); }
.card-storefronts .card-icon { background: var(--accent-cyan-dim); color: var(--accent-cyan); }
.card-agents .card-icon { background: rgba(188,140,255,0.12); color: var(--accent-purple); }

.product-card .card-icon svg { width: 24px; height: 24px; }

.product-card h3 { margin-bottom: 12px; }

.product-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  flex: 1;
}

.product-card .btn { align-self: flex-start; }

/* ─── CLI Setup Section ─── */
.cli-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.cli-section .section-header {
  margin-bottom: 48px;
}

.cli-section .section-header h2 { margin-bottom: 12px; }
.cli-section .section-header p { font-size: 1rem; }

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

.accordion-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-trigger {
  width: 100%;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background var(--transition-fast);
}
.accordion-trigger:hover { background: var(--bg-surface-hover); }

.accordion-trigger svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.accordion-item.active .accordion-trigger svg {
  transform: rotate(180deg);
}
.accordion-item.active .accordion-trigger {
  color: var(--accent-green);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow) ease;
}

.accordion-item.active .accordion-body {
  max-height: 500px;
}

.accordion-body-inner {
  padding: 0 20px 20px;
}

.accordion-body-inner ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-body-inner ol li {
  counter-increment: steps;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-body-inner ol li::before {
  content: counter(steps);
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-green-dim);
  color: var(--accent-green);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  margin-top: 1px;
}

.cli-code-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.pkg-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-default);
}

.pkg-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.pkg-tab:hover { color: var(--text-secondary); }
.pkg-tab.active {
  color: var(--accent-green);
  border-bottom-color: var(--accent-green);
}

.code-blocks { padding: 20px; }

.code-block {
  display: none;
}
.code-block.active { display: block; }

.code-block-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 8px;
}

.code-block pre {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: var(--radius-sm);
  padding: 14px 16px;
  overflow-x: auto;
  margin-bottom: 16px;
}

.code-block pre code {
  color: var(--text-primary);
  font-size: 0.8rem;
  line-height: 1.6;
}

.code-block pre code .cmd { color: var(--accent-cyan); }
.code-block pre code .flag { color: var(--accent-orange); }
.code-block pre code .str { color: var(--accent-green); }
.code-block pre code .comment { color: var(--text-muted); }

/* ─── Launch CTA Section ─── */
.launch-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.launch-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.launch-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition-base);
}
.launch-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.launch-card h3 { margin-bottom: 12px; }
.launch-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

/* ─── Community Section ─── */
.community-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.community-section h2 { margin-bottom: 32px; }

.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.community-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: all var(--transition-base);
  text-decoration: none;
  cursor: pointer;
}
.community-card:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface-hover);
  transform: translateY(-2px);
  color: var(--text-primary);
}
.community-card svg {
  width: 20px;
  height: 20px;
  color: var(--accent-cyan);
  flex-shrink: 0;
}
.community-card span { color: var(--text-secondary); font-weight: 400; font-size: 0.82rem; }

/* ─── Footer ─── */
.site-footer {
  border-top: 1px solid var(--border-default);
  padding: 60px 0 40px;
  margin-top: 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 40px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  font-size: 0.85rem;
  color: var(--text-secondary);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-subtle);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* ─── Docs Layout (Sidebar + Content) ─── */
.docs-layout {
  display: flex;
  min-height: calc(100vh - var(--nav-height));
}

.sidebar {
  width: var(--sidebar-width);
  border-right: 1px solid var(--border-default);
  padding: 24px 0;
  position: sticky;
  top: var(--nav-height);
  height: calc(100vh - var(--nav-height));
  overflow-y: auto;
  flex-shrink: 0;
  transition: width var(--transition-slow), padding var(--transition-slow), opacity var(--transition-base);
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: fixed;
  top: calc(var(--nav-height) + 16px);
  left: var(--sidebar-width);
  z-index: 50;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  padding: 6px;
  cursor: pointer;
  transition: all var(--transition-slow);
  display: flex;
  align-items: center;
  justify-content: center;
}
.sidebar-toggle:hover {
  color: var(--text-primary);
  border-color: var(--text-muted);
}
.sidebar-toggle svg { width: 16px; height: 16px; }

.sidebar.collapsed ~ .sidebar-toggle,
.sidebar-toggle.collapsed-pos {
  left: 8px;
}

.sidebar-nav {
  padding: 0 16px;
}

.sidebar-group { margin-bottom: 24px; }

.sidebar-group-title {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 0 12px;
  margin-bottom: 8px;
}

.sidebar-link {
  display: block;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}
.sidebar-link:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}
.sidebar-link.active {
  color: var(--accent-green);
  background: var(--accent-green-dim);
}

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px 48px 80px;
  max-width: 900px;
}

.docs-content section {
  margin-bottom: 64px;
}

.docs-content section h2 {
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-subtle);
}

.docs-content section > p {
  margin-bottom: 24px;
}

/* ─── Feature Grid (for surfaces, building blocks, etc.) ─── */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.feature-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 24px;
  transition: all var(--transition-base);
}
.feature-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.feature-card h4 {
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.feature-card h4 svg {
  width: 18px;
  height: 18px;
  color: var(--accent-green);
  flex-shrink: 0;
}

.feature-card p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ─── Best Practices List ─── */
.practices-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 12px;
}

.practice-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}

.practice-item svg {
  width: 18px;
  height: 18px;
  color: var(--accent-green);
  flex-shrink: 0;
  margin-top: 2px;
}

.practice-item strong {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
}

.practice-item span {
  font-size: 0.82rem;
  color: var(--text-secondary);
}

/* ─── Protocol Actors Diagram ─── */
.protocol-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  padding: 32px 0;
}

.actor-card {
  text-align: center;
  padding: 28px 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}
.actor-card:hover {
  border-color: var(--accent-purple);
  box-shadow: 0 0 20px rgba(188,140,255,0.1);
}

.actor-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: rgba(188,140,255,0.12);
  color: var(--accent-purple);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
}
.actor-icon svg { width: 24px; height: 24px; }

.actor-card h4 { margin-bottom: 6px; }
.actor-card p { font-size: 0.8rem; color: var(--text-muted); text-align: center; margin: 0 auto; }

/* ─── How-it-works Flow ─── */
.flow-cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.flow-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 28px;
  position: relative;
}

.flow-card .flow-label {
  font-family: var(--font-mono);
  font-size: 0.7rem;
  color: var(--accent-purple);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 12px;
}

.flow-card h3 { margin-bottom: 10px; }
.flow-card p { font-size: 0.875rem; color: var(--text-secondary); }

.badge-soon {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--accent-orange);
  background: rgba(240,136,62,0.12);
  padding: 2px 8px;
  border-radius: 999px;
  margin-left: 8px;
  vertical-align: middle;
}

/* ─── Support Categories ─── */
.support-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.support-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
}
.support-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-2px);
}
.support-card h4 { margin-bottom: 10px; }
.support-card ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.support-card li {
  font-size: 0.85rem;
  color: var(--text-secondary);
}

/* ─── Dev Tools Banner ─── */
.dev-tools-banner {
  background: linear-gradient(135deg, var(--bg-surface) 0%, var(--bg-elevated) 100%);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px;
  margin-bottom: 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.dev-tools-banner h3 { margin-bottom: 8px; }
.dev-tools-banner p { font-size: 0.9rem; }

/* ─── Section Utilities ─── */
.section-header {
  margin-bottom: 32px;
}
.section-header h2 { margin-bottom: 10px; }
.section-header p { font-size: 1rem; color: var(--text-secondary); }

.section-divider {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 0;
}

/* ─── Tag / Badge ─── */
.tag {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-mono);
  font-size: 0.7rem;
  font-weight: 500;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--accent-green-dim);
  color: var(--accent-green);
}

/* ─── Theming Cards ─── */
.theme-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 32px;
}

.theme-option {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  padding: 28px;
  transition: all var(--transition-base);
}
.theme-option:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}
.theme-option h4 { margin-bottom: 8px; }
.theme-option p { font-size: 0.85rem; color: var(--text-secondary); }

.highlights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 16px;
}

.highlight-item {
  padding: 20px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
}
.highlight-item h4 { margin-bottom: 6px; font-size: 0.95rem; }
.highlight-item p { font-size: 0.82rem; color: var(--text-secondary); }

/* ─── Inline code ─── */
.inline-code {
  font-family: var(--font-mono);
  font-size: 0.82em;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: 4px;
  padding: 2px 6px;
  color: var(--accent-orange);
}

/* ─── Mobile Responsive ─── */
@media (max-width: 1024px) {
  .product-cards { grid-template-columns: 1fr; }
  .cli-content { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .launch-cards { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: repeat(2, 1fr); }
  .flow-cards { grid-template-columns: 1fr; }
  .theme-options { grid-template-columns: 1fr; }

  .sidebar {
    position: fixed;
    left: 0;
    top: var(--nav-height);
    z-index: 90;
    background: var(--bg-primary);
    width: var(--sidebar-width);
  }
  .sidebar.collapsed { width: 0; }
  .sidebar-toggle {
    position: fixed;
    left: 8px;
  }
  .sidebar:not(.collapsed) ~ .sidebar-toggle { left: calc(var(--sidebar-width) + 4px); }
}

@media (max-width: 768px) {
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.35rem; }

  .nav-links, .nav-search { display: none; }
  .mobile-menu-btn { display: flex; }

  .nav-inner { gap: 8px; }

  .hero { padding: 48px 0 32px; }
  .hero .subtitle { font-size: 1rem; }
  .hero-ctas { flex-direction: column; align-items: center; }

  .product-cards { gap: 12px; padding-bottom: 48px; }
  .product-card { padding: 24px 20px; }

  .community-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
  .practices-list { grid-template-columns: 1fr; }
  .protocol-diagram { grid-template-columns: 1fr; }

  .docs-content { padding: 24px 20px 48px; }
  .dev-tools-banner { flex-direction: column; text-align: center; }

  .container { padding: 0 16px; }
  .cli-section, .launch-section, .community-section { padding: 48px 0; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
}

/* ─── Mobile Nav Menu ─── */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 99;
  padding: 24px;
  flex-direction: column;
  gap: 8px;
  border-top: 1px solid var(--border-default);
}
.mobile-nav.open { display: flex; }

.mobile-nav a {
  display: block;
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.mobile-nav a:hover, .mobile-nav a.active {
  color: var(--text-primary);
  background: var(--bg-surface);
}

/* ─── Reduced Motion ─── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
  html { scroll-behavior: auto; }
}

/* ─── Scrollbar ─── */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb {
  background: var(--border-default);
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

raw_arguments.content:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-primary: #0d1117;
  --bg-surface: #161b22;
  --bg-surface-hover: #1c2330;
  --bg-elevated: #21262d;
  --border-default: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent-green: #00e87b;
  --accent-green-dim: rgba(0, 232, 123, 0.15);
  --accent-cyan: #58a6ff;
  --accent-cyan-dim: rgba(88, 166, 255, 0.12);
  --accent-orange: #f0883e;
  --accent-purple: #bc8cff;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --font-sans: 'IBM Plex Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', Consolas, monospace;
  --radius-sm: 6px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
  --shadow-glow-green: 0 0 20px rgba(0,232,123,0.15);
  --shadow-glow-cyan: 0 0 20px rgba(88,166,255,0.15);
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 64px;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: var(--accent-cyan);
  text-decoration: none;
  transition: color var(--transition-fast);
}
a:hover { color: var(--accent-green); }
a:focus-visible {
  outline: 2px solid var(--accent-cyan);
  outline-offset: 2px;
  border-radius: 2px;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-primary);
}

h1 { font-size: 2.5rem; letter-spacing: -0.02em; }
h2 { font-size: 1.75rem; letter-spacing: -0.01em; }
h3 { font-size: 1.25rem; }
h4 { font-size: 1.1rem; }

p { color: var(--text-secondary); max-width: 68ch; }

code, pre {
  font-family: var(--font-mono);
  font-size: 0.875rem;
}

/* ─── Top Navigation ─── */
.top-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-default);
  z-index: 100;
  display: flex;
  align-items: center;
  padding: 0 24px;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--text-primary);
  white-space: nowrap;
}

.nav-logo svg {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  display: inline-flex;
  align-items: center;
  padding: 8px 14px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
  cursor: pointer;
}

.nav-links a:hover {
  color: var(--text-primary);
  background: var(--bg-surface);
}

.nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-elevated);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  font-size: 0.8rem;
  color: var(--text-muted);
  cursor: pointer;
  transition: border-color var(--transition-fast);
}
.nav-search:hover { border-color: var(--text-muted); }
.nav-search svg { width: 14px; height: 14px; opacity: 0.6; }
.nav-search kbd {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  padding: 1px 5px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-default);
  border-radius: 4px;
  color: var(--text-muted);
}

.nav-login {
  padding: 6px 16px;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  background: transparent;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.nav-login:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 8px;
}
.mobile-menu-btn svg { width: 24px; height: 24px; }

/* ─── Main Content Area ─── */
main {
  margin-top: var(--nav-height);
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Hero Section ─── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 20px;
  background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-green) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero .subtitle {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 20px;
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: all var(--transition-base);
  text-decoration: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
  border-color: var(--accent-green);
}
.btn-primary:hover {
  background: #00ff88;
  color: #0d1117;
  box-shadow: var(--shadow-glow-green);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border-color: var(--border-default);
}
.btn-secondary:hover {
  border-color: var(--text-muted);
  background: var(--bg-surface);
  transform: translateY(-1px);
}

.btn-ghost {
  background: transparent;
  color: var(--accent-cyan);
  padding: 8px 12px;
}
.btn-ghost:hover {
  background: var(--accent-cyan-dim);
  color: var(--accent-cyan);
}

/* ─── Product Cards ─── */
.product-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  padding-bottom: 80px;
}

.product-card {
  position: relative;
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  transition: opacity var(--transition-base);
  opacity: 0.7;
}
.product-card:hover {
  border-color: var(--text-muted);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-card:hover::before { opacity: 1; }

.product-card.card-apps::before { background: var(--accent-green); }
.product-card.card-storefronts::before { background: var(--accent-cyan); }
.product-card.card-agents::before { background: var(--accent-purple); }

.product-card .card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}
.card-apps .card-icon { background: var(--accent-green-dim); color: var(--accent-green); }
.card-storefronts .card-icon { background: var(--accent-cyan-dim); color: var(--accent-cyan); }
.card-agents .card-icon { background: rgba(188,140,255,0.12); color: var(--accent-purple); }

.product-card .card-icon svg { width: 24px; height: 24px; }

.product-card h3 { margin-bottom: 12px; }

.product-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 24px;
  flex: 1;
}

.product-card .btn { align-self: flex-start; }

/* ─── CLI Setup Section ─── */
.cli-section {
  padding: 80px 0;
  border-top: 1px solid var(--border-subtle);
}

.cli-section .section-header {
  margin-bottom: 48px;
}

.cli-section .section-header h2 { margin-bottom: 12px; }
.cli-section .section-header p { font-size: 1rem; }

.cli-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  align-items: start;
}

.accordion-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.accordion-item {
  border: 1px solid var(--border-default);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-surface);
}

.accordion-trigger {
  width: 100%;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-family: var(--font-sans);
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: space-between;
  transition: background var(--transition-fast);
}
.accordion-trigger:hover { background: var(--bg-surface-hover); }

.accordion-trigger svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition-base);
  flex-shrink: 0;
}

.accordion-item.active .accordion-trigger svg {
  transform: rotate(180deg);
}
.accordion-item.active .accordion-trigger {
  color: var(--accent-green);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow) ease;
}

.accordion-item.active .accordion-body {
  max-height: 500px;
}

.accordion-body-inner {
  padding: 0 20px 20px;
}

.accordion-body-inner ol {
  list-style: none;
  counter-reset: steps;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-body-inner ol li {
  counter-increment: steps;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.accordion-body-inner ol li::before {
  content: counter(steps);
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-green-dim);
  color: var(--accent-green);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  margin-top: 1px;
}

.cli-code-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.pkg-tabs {
  display: flex;
  border-bottom: 1px solid var(--border-default);
}

.pkg-tab {
  padding: 10px 20px;
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition-fast);
}
.pkg-tab:hover { color: var(--text-secondary); }
.pkg-tab.active {
  color: var(--accent-green);
  border-bottom-color: var(--accent-green);
}

