import re, os

pages = ['index.html', 'apps-build.html', 'storefronts.html', 'agents.html', 'support.html']
issues = []

for page in pages:
    if not os.path.exists(page):
        issues.append(f'MISSING: {page}')
        continue
    with open(page) as f:
        html = f.read()
    # Check essential elements
    if 'assets/styles.css' not in html:
        issues.append(f'{page}: missing CSS link')
    if 'assets/script.js' not in html:
        issues.append(f'{page}: missing JS link')
    if '<nav' not in html:
        issues.append(f'{page}: missing nav')
    if '<footer' not in html:
        issues.append(f'{page}: missing footer')
    if 'role=\"navigation\"' not in html:
        issues.append(f'{page}: missing nav role')
    if 'viewport' not in html:
        issues.append(f'{page}: missing viewport meta')

    # Check cross-page links
    for target in pages:
        if target != page and target in ['index.html', 'apps-build.html', 'storefronts.html', 'agents.html', 'support.html']:
            pass  # will check specific navigation links

# Check index.html specifics
with open('index.html') as f:
    idx = f.read()
if 'accordion' not in idx:
    issues.append('index.html: missing accordion')
if 'pkg-tab' not in idx:
    issues.append('index.html: missing package manager tabs')
if 'product-card' not in idx:
    issues.append('index.html: missing product cards')
if 'community' not in idx.lower():
    issues.append('index.html: missing community section')

# Check apps-build.html specifics
with open('apps-build.html') as f:
    apps = f.read()
if 'sidebar' not in apps:
    issues.append('apps-build.html: missing sidebar')
if 'sidebar-toggle' not in apps:
    issues.append('apps-build.html: missing sidebar toggle')

# Check agents.html specifics
with open('agents.html') as f:
    agents = f.read()
if 'sidebar' not in agents:
    issues.append('agents.html: missing sidebar')
if 'protocol' not in agents.lower():
    issues.append('agents.html: missing protocol content')
if 'Coming soon' not in agents:
    issues.append('agents.html: missing coming soon badge')

# Check support.html specifics
with open('support.html') as f:
    support = f.read()
if 'Partner Program' not in support:
    issues.append('support.html: missing Partner Program')
if 'Contact us' not in support:
    issues.append('support.html: missing contact CTA')

if issues:
    print('ISSUES FOUND:')
    for i in issues:
        print(f'  - {i}')
else:
    print('ALL CHECKS PASSED')
"

